+static inline char complement_base(char base) {
+    switch (base) {
+    case 'A': return 'T';
+    case 'C': return 'G';
+    case 'G': return 'C';
+    case 'T': return 'A';
+    default:
+        return 'N';
+    }
+}
+
+static inline std::string complement_string(std::string const &str) {
+    std::string result(str);
+    std::transform(result.begin(), result.end(), result.begin(), complement_base);
+    return result;
+}
